    {
      "ref": "RFC6749 §10.5 ¶4",
      "rfc": 6749,
      "section": "Authorization Codes",
      "figure": false,
      "text": "If the client can be authenticated, the authorization servers MUST authenticate the client and ensure that the authorization code was issued to the same client."
    },
    {
      "ref": "RFC9700 §4.5 ¶1",
      "rfc": 9700,
      "section": "Authorization Code Injection",
      "figure": false,
      "text": "An attacker who has gained access to an authorization code contained in an authorization response (see Attacker (A3) in Section 3) can try to redeem the authorization code for an access token or otherwise make use of the authorization code."
